from scirel.fusion import advance_halo_iteration_feedback_sequence
result = advance_halo_iteration_feedback_sequence({
    'dcx_density_cm3': 100.0,
    'initial_previous_halo_density_cm3': 100.0,
    'initial_merged_halo_density_cm3': 0.0,
    'current_halo_densities_cm3': [55.9, 27.4, 15.7, 3.55, 0.315],
    'requested_halo_marker_budgets': [40, 22, 10, 6, 1],
    'source_halo_marker_budget': 40,
})
assert result['final_state']['stop_reason'] == 'seed_below_threshold'
assert result['diagnostics']['branch_counts'] == {'continue': 4, 'seed_below_threshold': 1}
assert [r['requested_halo_marker_budget'] for r in result['iterations']] == [40, 22, 10, 6, 1]
try:
    advance_halo_iteration_feedback_sequence({'dcx_density_cm3': 100.0, 'initial_previous_halo_density_cm3': 100.0, 'initial_merged_halo_density_cm3': 0.0, 'current_halo_densities_cm3': [55.9, 27.4], 'requested_halo_marker_budgets': [40, 40], 'source_halo_marker_budget': 40})
except ValueError:
    pass
else:
    raise AssertionError('marker-budget drift must fail closed')
